def verify(obj):
 if isinstance(obj,dict):
  if 'path' in obj and 'sha256' in obj:assert bind(obj['path'])['sha256']==obj['sha256'],obj['path']
  for v in obj.values():verify(v)
 elif isinstance(obj,list):
  for v in obj:verify(v)

